export const same = (a, b) => a.key.toLowerCase() === b.key.toLowerCase() && !!a.meta === !!b.meta && !!a.alt === !!b.alt && !!a.shift === !!b.shift;
// Atalhos personalizados (Configurações › atalhos) ficam em S.keys, pelo índice no KEYMAP, e valem para teclas e dicas.
const matchOf = (S, e) => S?.keys?.[KEYMAP.indexOf(e)] ?? e.match;
const lookup = (S, ev, scope) => KEYMAP.find(e => e.scope === scope && same(matchOf(S, e), ev))?.action ?? null;
const ARROWS = { ArrowLeft: '←', ArrowRight: '→', ArrowUp: '↑', ArrowDown: '↓', Enter: '↵', Backspace: '⌫', Escape: 'esc', ' ': 'espaço' };
export const keyLabel = m => `${m.meta ? '⌘' : ''}${m.alt ? '⌥' : ''}${m.shift ? '⇧' : ''}${ARROWS[m.key] ?? m.key.toUpperCase()}`;
export const keysOf = (S, e) => S?.keys?.[KEYMAP.indexOf(e)] ? keyLabel(S.keys[KEYMAP.indexOf(e)]) : e.keys;

export function resolveKey(S, raw) {
  const ev = { key: raw.key, meta: !!(raw.meta || raw.ctrl), alt: !!raw.alt, shift: !!raw.shift };
  const { key, meta, alt } = ev;
  const ov = S.overlay;
  if (ov?.kind === 'capture') return key === 'Escape' && !meta ? { type: 'ESC' } : /^(Meta|Control|Alt|Shift)$/.test(key) ? null : { type: 'OP', pane: ov.pane, op: { op: 'fn', name: 'capture', match: { key, meta, alt, shift: ev.shift } } };
  if (raw.ctrl && !raw.meta && (key === 'c' || key === 'r')) return { type: key === 'c' ? 'INTERRUPT' : 'HISTORY' };
  if (ov?.kind === 'jump') {
    if (!meta && jumpLabels(S).some(l => l.label === key)) return { type: 'JUMP_TO', label: key };
    if (!meta) return { type: 'ESC' };
  } else if (ov?.kind === 'mention') {
    const M = op => ({ type: 'MENTION', op });
    if (meta) return key === 'c' ? M('copy') : key === 'Enter' ? M('finder') : key === 'Backspace' ? M('delete') : null;
    if (key === 'Tab') return M('filter');
    if (key === ' ') return M('pick');
    if (key === 'ArrowLeft' || key === 'ArrowRight') return M('scope');
    if (key === 'Enter') return { type: 'OP', pane: ov.pane, op: { op: 'fn', name: 'mentionInsert' } };
    if (key === 'Escape') return { type: 'ESC' };
    if (key === 'ArrowDown' || key === 'ArrowUp') return { type: 'OV_MOVE', d: key === 'ArrowDown' ? 1 : -1 };
    if (key === 'Backspace') return { type: 'OV_EDIT', op: 'back' };
    return key.length === 1 ? { type: 'OV_TYPE', text: key } : null;
  } else if (ov?.kind === 'notice') {
    return { type: 'NOTICE', key };
  } else if (ov?.kind === 'confirm') {
    if (!meta) return key === 'y' || key === 'Enter' ? { type: 'CONFIRM' } : key === 'n' || key === 'Escape' ? { type: 'ESC' } : null;
  } else if (ov) {
    if (key === 'Escape') return { type: 'ESC' };
    if (key === 'Enter') return ov.kind === 'find' && ev.shift ? { type: 'FIND_STEP', d: -1 } : { type: 'OV_ACCEPT' };
    if (key === 'ArrowDown' || key === 'Tab') return { type: 'OV_MOVE', d: 1 };
    if (key === 'ArrowUp') return { type: 'OV_MOVE', d: -1 };
    if (key === 'Backspace') return { type: 'OV_EDIT', op: meta || alt ? 'clear' : 'back' };
    if (ov.kind === 'acts' && !meta && key.length === 1) return ov.items.some(i => i.key === key) ? { type: 'ACT', key } : null;
    if (!meta && key.length === 1) return { type: 'OV_TYPE', text: key };
    if (!meta) return null;
  }
  if (meta) {
    const g = lookup(S, ev, 'global');
    if (g) return g;
    const own = !S.ui.side && !S.overlay && keyLabel(ev);
    if (own && (plugin(focused(S).plugin)?.keys?.(focused(S), S) ?? []).includes(own)) return { type: 'PKEY', key: own };
    if (!alt && key === 'ArrowLeft') return { type: 'EDIT', op: 'home' };
    if (!alt && key === 'ArrowRight') return { type: 'EDIT', op: 'end' };
    if (key === 'Backspace') return { type: 'EDIT', op: 'lineBack' };
    if (key === 'Enter' && !alt && !ev.shift && !S.ui.side && !S.overlay && focused(S).input.text) return { type: 'SUBMIT' };
    return null;
  }
  if (S.ui.side) return lookup(S, ev, 'sidebar');
  const leaf = focused(S), text = leaf.input.text;
  if (key === 'Enter' && ev.shift) return { type: 'EDIT', op: 'newline' }; // texto de várias linhas (Chat, campos longos)
  if (leaf.data.editing && key === 'Enter') return { type: 'SUBMIT' };
  const item = () => linesOf(leaf, S).filter(l => l.id)[leaf.cursor];
  // Filtrar e agir: com texto numa vista que filtra, ↵ age no item destacado; sem resultado, ↵ envia (cria). ⌘↵ sempre envia.
  if (key === 'Enter' && text && !text.startsWith('/')) {
    const v = viewsOf(leaf.plugin, leaf).find(x => x.id === leaf.data.view);
    if (v && (v.list || v.blocks || v.filter)) return item() ? { type: 'ACTIVATE', clear: true } : { type: 'SUBMIT' };
  }
  // Na ficha, ⇥ e ⇧⇥ andam entre os campos em vez de trocar de vista.
  if (key === 'Tab' && leaf.data.view === 'ficha' && !text.startsWith('/')) return { type: 'CURSOR', d: ev.shift ? -1 : 1, wrap: true };
  if (!text && key === '.' && (actionsFor(leaf, item(), S).length || plugin(leaf.plugin)?.actions?.(leaf, item(), S)?.length)) return { type: 'ACTS' };
  if (key === 'Tab' && text && !text.startsWith('/') && plugin(leaf.plugin)?.complete) return { type: 'COMPLETE_PATH' };
  if (key === 'Tab' && !text.startsWith('/') && viewsOf(leaf.plugin, leaf).length > 1) return { type: 'VIEW', d: ev.shift ? -1 : 1 };
  if (!text && (key === 'ArrowLeft' || key === 'ArrowRight') && viewsOf(leaf.plugin, leaf).find(v => v.id === leaf.data.view)?.sub) return { type: 'SUB', d: key === 'ArrowLeft' ? -1 : 1 };
  if (!text && !alt && (plugin(leaf.plugin)?.keys?.(leaf, S) ?? []).includes(key)) return { type: 'PKEY', key };
  if (text.startsWith('/') && completions(S, leaf).length) {
    if (key === 'ArrowDown') return { type: 'COMPLETE_MOVE', d: 1 };
    if (key === 'ArrowUp') return { type: 'COMPLETE_MOVE', d: -1 };
    if (key === 'Tab') return { type: 'COMPLETE' };
  }
  // Listas longas: Home/End vão ao primeiro e ao último item; PageUp/PageDown andam 10.
  if (!text && (key === 'Home' || key === 'End')) return { type: 'CURSOR', to: key === 'Home' ? 0 : -1 };
  if (key === 'PageUp' || key === 'PageDown') return { type: 'CURSOR', d: key === 'PageUp' ? -10 : 10 };
  switch (key) {
    case 'Enter': return text ? { type: 'SUBMIT' } : { type: 'ACTIVATE' };
    case 'Escape': return { type: 'ESC' };
    case 'Backspace': return { type: 'EDIT', op: alt ? 'wordBack' : 'back' };
    case 'Delete': return { type: 'EDIT', op: 'del' };
    case 'ArrowLeft': return { type: 'EDIT', op: alt ? 'wordLeft' : 'left' };
    case 'ArrowRight': return { type: 'EDIT', op: alt ? 'wordRight' : 'right' };
    case 'Home': return { type: 'EDIT', op: 'home' };
    case 'End': return { type: 'EDIT', op: 'end' };
    case 'ArrowUp': return { type: 'CURSOR', d: -1 };
    case 'ArrowDown': return { type: 'CURSOR', d: 1 };
    default: return key.length === 1 ? { type: 'TYPE', text: key } : null;
  }
}

export const hintFor = (action, S) => { const e = KEYMAP.find(x => x.scope === 'global' && JSON.stringify(x.action) === JSON.stringify(action)); return e ? keysOf(S, e) : ''; };

const KEY_LABEL = { ' ': 'espaço', ArrowRight: '→', ArrowLeft: '←' };
// ⌘/ Atalhos: o que vale nesta folha (do item, da vista e do plugin) e os atalhos globais, com os personalizados.
export function helpResults(S, query) {
  const leaf = focused(S), p = plugin(leaf.plugin), item = selectable(leaf, S)[leaf.cursor];
  const views = viewsOf(leaf.plugin, leaf), v = views.find(x => x.id === leaf.data.view), here = `nesta folha · ${p?.title ?? 'vazia'}${v ? ` · ${v.label}` : ''}`;
  const rows = [
    item && { keys: '↵', label: 'ação principal do item', action: { type: 'ACTIVATE' } },
    ...(p?.keys?.(leaf, S) ?? []).filter(k => k === ' ' ? item : p.keyHelp?.[k]).map(k => ({ keys: KEY_LABEL[k] ?? k, label: k === ' ' ? 'alternar o item' : p.keyHelp[k], action: { type: 'PKEY', key: k } })),
    ...KEYMAP.filter(e => e.scope === 'leaf' && e.keys !== '↵').map(e => ({ keys: e.keys, label: e.label, action: e.action })),
    ...(item ? actsOf(S, leaf, item) : []).map(a => ({ keys: `. ${a.key}`, label: a.label, action: { type: 'ACT', key: a.key } })),
    ...(views.length > 1 ? views.map(x => ({ keys: '⇥', label: `vista ${x.label}`, action: { type: 'OP', pane: leaf.id, op: { op: 'view', view: x.id } } })) : []),
    v?.sub && { keys: '← →', label: `sub-filtro: ${v.sub.map(x => x.label).join(' · ')}`, action: { type: 'SUB', d: 1 } },
    ...(p?.commands ?? []).map(c => ({ keys: `/${c.name}`, label: c.desc ?? c.name, action: { type: 'SET_INPUT', text: `/${c.name} ` } })),
  ].filter(Boolean).map(x => ({ ...x, section: here }));
  const global = KEYMAP.filter(e => e.scope === 'global' && !/^⌘[2-9]$/.test(e.keys))
    .map(e => ({ section: 'global', keys: e.keys === '⌘1' ? '⌘1…9' : keysOf(S, e), label: e.keys === '⌘1' ? 'aba pela posição' : e.label, action: e.action }));
  return [...rows, ...global].map(x => ({ ...x, label: x.label[0].toUpperCase() + x.label.slice(1) })).map((x, i) => ({ x, s: score(query, `${x.label} ${x.keys}`), i })).filter(r => r.s > 0)
    .sort((a, b) => (query ? b.s - a.s : 0) || a.i - b.i).map(r => r.x);
}

// ⌘⇧A Agentes: tudo o que está acontecendo em todas as abas, do mais urgente ao mais calmo. ↵ leva à folha.
export function agentResults(S, query) {
  return activities(S).map(({ tab, leaf, a }) => ({ section: a.state, state: a.state, unread: a.unread, label: a.title ? `${a.who}: ${a.title}` : `${plugin(leaf.plugin)?.title ?? 'folha'}${plugin(leaf.plugin)?.view(leaf, S).subject ? ` ${plugin(leaf.plugin).view(leaf, S).subject}` : ''}`, keys: [a.label, a.elapsed, tab.title].filter(Boolean).join(' · '), action: { type: 'FOCUS', id: leaf.id } }))
    .filter(r => score(query, `${r.label} ${r.keys} ${r.state}`) > 0);
}

// Listas de busca: paleta, seletores e /comandos.
const HOST = MANIFESTS.host.palette;

export function paletteResults(S, query) {
  const on = new Set(available(S).map(p => p.id));
  const all = [
    ...HOST.map(([label, action]) => ({ kind: 'host', label, action })),
    ...available(S).map(p => ({ kind: 'plugin', plugin: p.id, label: `Abrir ${p.title}`, action: { type: 'GOTO', plugin: p.id } })),
    ...(query ? CAPABILITIES.filter(c => c.plugin === 'host' || on.has(c.plugin)).map(c => ({
      kind: 'cap', plugin: c.plugin, command: c.command, module: c.module,
      label: `${c.plugin === 'host' ? 'janela' : plugin(c.plugin).title} › ${c.slug}`, action: { type: 'RUN', plugin: c.plugin, command: c.slug },
    })) : []),
  ];
  const recent = S.recent ?? [], rank = r => { const k = recent.indexOf(r.label); return k < 0 ? 99 : k; };
  return all.map((r, i) => ({ r, s: Math.max(score(query, r.label), r.command ? score(query, r.command) : 0, r.kind === 'plugin' ? score(query, plugin(r.plugin).title) : 0), i }))
    .filter(x => x.s > 0).sort((a, b) => b.s - a.s || rank(a.r) - rank(b.r) || a.i - b.i).slice(0, 60)
    .map(x => query || !recent.length ? x.r : { ...x.r, section: recent.includes(x.r.label) ? 'recentes' : 'ações e plugins' });
}

export function completions(S, leaf) {
  const text = leaf.input.text;
  if (!text.startsWith('/')) return [];
  const q = text.slice(1).split(/\s+/)[0];
  const p = plugin(leaf.plugin);
  if (!p) return [];
  const list = [...(p.commands ?? []).map(c => ({ name: c.name, desc: c.desc, native: true })),
    ...CAPABILITIES.filter(c => c.plugin === p.id).map(c => ({ name: c.slug, desc: `prévia · ${c.module}` }))];
  return list.filter(c => score(q, c.name) >= 2 || !q);
}

export const pickResults = (S, ov) => ov.mode === 'choose' ? ov.items.filter(i => score(ov.query, i.label) > 0)
  : ov.mode === 'history'
  ? [...new Set(findLeaf(S, ov.pane)?.leaf.data.history ?? [])].reverse().filter(c => score(ov.query, c) > 0).map(c => ({ label: c, action: { type: 'SET_INPUT', text: c } }))
  : ov.mode === 'group'
  ? S.groups.filter(g => score(ov.query, g.name) > 0).map(g => ({ label: g.name, action: { type: 'MOVE_TAB', tab: ov.tab, group: g.id } }))
  : available(S).map(p => ({ p, s: Math.max(score(ov.query, p.title), score(ov.query, p.id), score(ov.query, p.keywords ?? '')) }))
    .filter(x => x.s > 0).sort((a, b) => b.s - a.s).map(({ p }) => ({ label: p.title, plugin: p.id, action: { type: 'OPEN', plugin: p.id, pane: ov.pane } }));
